// game.js – simple endless‑scroll spaceship game
// Canvas with id "game" must exist in the HTML.

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return console.error('Canvas #game not found');
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 800;
  const height = canvas.height = canvas.clientHeight || 600;

  // --- Game objects -------------------------------------------------------
  const ship = {
    x: width / 2,
    y: height - 60,
    w: 30,
    h: 40,
    speed: 5,
    dx: 0,
    dy: 0,
    draw() {
      ctx.fillStyle = '#0ff';
      ctx.beginPath();
      ctx.moveTo(this.x, this.y);
      ctx.lineTo(this.x - this.w / 2, this.y + this.h);
      ctx.lineTo(this.x + this.w / 2, this.y + this.h);
      ctx.closePath();
      ctx.fill();
    },
    update() {
      this.x += this.dx;
      this.y += this.dy;
      // keep inside canvas
      this.x = Math.max(this.w / 2, Math.min(width - this.w / 2, this.x));
      this.y = Math.max(0, Math.min(height - this.h, this.y));
    },
  };

  const asteroids = [];
  const powerUps = [];
  let frame = 0;
  let score = 0;
  let gameOver = false;

  // --- Helpers -----------------------------------------------------------
  function rand(min, max) {
    return Math.random() * (max - min) + min;
  }

  function spawnAsteroid() {
    const size = rand(20, 50);
    asteroids.push({
      x: rand(size / 2, width - size / 2),
      y: -size,
      r: size / 2,
      speed: rand(2, 5),
    });
  }

  function spawnPowerUp() {
    const size = 15;
    powerUps.push({
      x: rand(size, width - size),
      y: -size,
      r: size / 2,
      speed: 3,
    });
  }

  function circleCollision(a, b) {
    const dx = a.x - b.x;
    const dy = a.y - b.y;
    const dist = Math.hypot(dx, dy);
    return dist < a.r + b.r;
  }

  // --- Input -------------------------------------------------------------
  const keys = {};
  window.addEventListener('keydown', e => { keys[e.key] = true; });
  window.addEventListener('keyup', e => { keys[e.key] = false; });

  function handleInput() {
    ship.dx = 0;
    ship.dy = 0;
    if (keys.ArrowLeft) ship.dx = -ship.speed;
    if (keys.ArrowRight) ship.dx = ship.speed;
    if (keys.ArrowUp) ship.dy = -ship.speed;
    if (keys.ArrowDown) ship.dy = ship.speed;
  }

  // --- Main loop ----------------------------------------------------------
  function update() {
    if (gameOver) return;
    frame++;
    if (frame % 60 === 0) spawnAsteroid(); // one per second
    if (frame % 300 === 0) spawnPowerUp(); // every 5 seconds

    handleInput();
    ship.update();

    // move asteroids
    for (let i = asteroids.length - 1; i >= 0; i--) {
      const a = asteroids[i];
      a.y += a.speed;
      // collision with ship
      if (circleCollision({x: ship.x, y: ship.y, r: ship.w / 2}, a)) {
        gameOver = true;
      }
      // remove off‑screen
      if (a.y - a.r > height) asteroids.splice(i, 1);
    }

    // move power‑ups
    for (let i = powerUps.length - 1; i >= 0; i--) {
      const p = powerUps[i];
      p.y += p.speed;
      if (circleCollision({x: ship.x, y: ship.y, r: ship.w / 2}, p)) {
        score += 10;
        powerUps.splice(i, 1);
        continue;
      }
      if (p.y - p.r > height) powerUps.splice(i, 1);
    }
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // ship
    ship.draw();
    // asteroids
    ctx.fillStyle = '#888';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // power‑ups
    ctx.fillStyle = '#ff0';
    powerUps.forEach(p => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '20px sans-serif';
    ctx.fillText('Score: ' + score, 10, 30);
    // game over overlay
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#f00';
      ctx.textAlign = 'center';
      ctx.font = '40px sans-serif';
      ctx.fillText('Game Over', width / 2, height / 2);
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  // start the game
  requestAnimationFrame(loop);
})();
